import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const credentials = {
        userid: email,
        password: password,
      };

      const query = new URLSearchParams({
        ApiVer: "1",
        Devid: "online",
        AppId: "NV01",
        Lat: "0",
        Lng: "0",
        Control: "auth",
        data: JSON.stringify(credentials),
      });

      const apiURL = `https://novaoffice.novasoftwares.com/service.aspx?${query.toString()}`;

      const response = await fetch(apiURL);
      const data = await response.json();

      console.log("API Response:", data);

      // Handle successful login (assuming not Result: "error")
      if (Array.isArray(data) && data[0]?.Result !== "error") {
        navigate("/dashboard", { state: { data } });
      } else {
        setError("Invalid credentials. Please try again.");
      }
    } catch (err) {
      console.error("Login error:", err);
      setError("Something went wrong. Please try again.");
    }
  };

  return (
    <div className="container">
      <h1>Login</h1>
      <form onSubmit={handleLogin}>
        <div className="field">
          <label>User ID</label>
          <input
            type="text"
            name="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Enter User ID"
          />
        </div>
        <div className="field">
          <label>Password</label>
          <input
            type="password"
            name="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Enter Password"
          />
        </div>
        <button className="fluid ui button blue" type="submit">
          Login
        </button>
        {error && <p style={{ color: "red", marginTop: "10px" }}>{error}</p>}
      </form>
      <div className="text" style={{ marginTop: "1rem", textAlign: "center" }}>
        Don't have an account? <Link to="/signup">Sign up</Link>
      </div>
    </div>
  );
}

export default Login;
